select case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end as sale_cohort, max(i.last_restock) as last_last_restock, max(i.quantity) as max_quantity from inventory i inner join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id group by case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end order by max_quantity;
